function fmt$(n) {
  if (n >= 1e12) return '$' + (n/1e12).toFixed(2) + 'T';
  if (n >= 1e9)  return '$' + (n/1e9).toFixed(2)  + 'B';
  if (n >= 1e6)  return '$' + (n/1e6).toFixed(2)  + 'M';
  if (n >= 1000) return '$' + n.toLocaleString('en-US', {maximumFractionDigits:2});
  return '$' + n.toLocaleString('en-US', {minimumFractionDigits:2,maximumFractionDigits:6});
}

function fmtPct(n) {
  const sign = n >= 0 ? '+' : '';
  return sign + n.toFixed(2) + '%';
}

function pctClass(n) {
  if (n > 0.005) return 'up';
  if (n < -0.005) return 'down';
  return 'flat';
}

// ═══════════════════════════════════════════════════════════════
//  SPARKLINE SVG
// ═══════════════════════════════════════════════════════════════
function mkSparkline(patIdx, trend) {
  const pts = SPARKLINE_PATTERNS[patIdx] || SPARKLINE_PATTERNS[0];
  const W = 100, H = 34, PAD = 2;
  const xs = pts.map((_,i) => PAD + i*(W-PAD*2)/(pts.length-1));
  const ys = pts.map(v => H - PAD - v*(H-PAD*2));
  const color = trend >= 0 ? '#16c784' : '#ea3943';
  const fillColor = trend >= 0 ? 'rgba(22,199,132,0.08)' : 'rgba(234,57,67,0.08)';

  let d = `M ${xs[0]} ${ys[0]}`;
  for (let i=1;i<xs.length;i++) {
    const mx = (xs[i-1]+xs[i])/2;
    d += ` C ${mx} ${ys[i-1]} ${mx} ${ys[i]} ${xs[i]} ${ys[i]}`;
  }
  const fill = d + ` L ${xs[xs.length-1]} ${H-PAD} L ${xs[0]} ${H-PAD} Z`;

  return `<svg class="sparkline-svg" width="100" height="34" viewBox="0 0 ${W} ${H}" aria-hidden="true">
    <path d="${fill}" fill="${fillColor}" stroke="none"/>
    <path d="${d}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
}

