    ${cols['1h']  ? `<td class="td-num"><span class="pct-val up">+0.21%</span></td>` : ''}
    ${cols['24h'] ? `<td class="td-num"><span class="pct-val up">+1.15%</span></td>` : ''}
    ${cols['7d']  ? `<td class="td-num"><span class="pct-val up">+4.97%</span></td>` : ''}
    ${cols.mcap   ? `<td class="td-num">—</td>` : ''}
    ${cols.vol    ? `<td class="td-num">—</td>` : ''}
    ${cols.supply ? `<td class="td-num">—</td>` : ''}
    ${cols.spark  ? `<td class="sparkline-cell">${mkSparkline(1,1)}</td>` : ''}
  </tr>`;

  page.forEach(c => {
    const coinColor = COIN_COLORS[c.rank % COIN_COLORS.length];
    const isStarred = state.starred.has(c.rank);
    html += `<tr tabindex="0" aria-label="${c.name} ${c.ticker}">
      <td style="width:44px;">
        <div style="display:flex;align-items:center;gap:4px;">
          <button class="star-btn ${isStarred?'starred':''}" onclick="toggleStar(event,${c.rank})" aria-label="${isStarred?'Remove from':'Add to'} watchlist">★</button>
          <span class="rank-num">${c.rank}</span>
        </div>
      </td>
      <td>
        <div class="coin-cell">
          <div class="coin-icon" style="background:${coinColor};">${getInitials(c.name)}</div>
          <div>
            <div class="coin-name">${c.name}</div>
            <div class="coin-ticker">${c.ticker}</div>
          </div>
        </div>
      </td>
      ${cols.price  ? `<td class="td-num">${fmt$(c.price)}</td>` : ''}
      ${cols['1h']  ? `<td class="td-num"><span class="pct-val ${pctClass(c.h1)}">${fmtPct(c.h1)}</span></td>` : ''}
      ${cols['24h'] ? `<td class="td-num"><span class="pct-val ${pctClass(c.h24)}">${fmtPct(c.h24)}</span></td>` : ''}
      ${cols['7d']  ? `<td class="td-num"><span class="pct-val ${pctClass(c.w7)}">${fmtPct(c.w7)}</span></td>` : ''}
      ${cols.mcap   ? `<td class="td-num">${fmt$(c.mcap)}</td>` : ''}
      ${cols.vol    ? `<td class="td-num td-muted">${fmt$(c.vol)}</td>` : ''}
      ${cols.supply ? `<td class="td-num td-muted" style="font-size:12px;">${c.supply}</td>` : ''}
      ${cols.spark  ? `<td class="sparkline-cell">${mkSparkline(c.pat, c.w7)}</td>` : ''}
    </tr>`;
  });

  tbody.innerHTML = html;

  // Pagination info
  const total = filteredCoins.length;
  const end = Math.min(start + PAGE_SIZE, total);
  document.getElementById('paginationInfo').textContent =
    `Showing ${start+1}–${end} of ${total.toLocaleString()} assets`;

  // Update col header visibility
  updateColVisibility();
  updateSortHeaders();
}

function updateColVisibility() {
  const { cols } = state;
  const maps = {price:'col-price','1h':'col-1h','24h':'col-24h','7d':'col-7d',mcap:'col-mcap',vol:'col-vol',supply:'col-supply',spark:'col-spark'};
  Object.entries(maps).forEach(([k,cls]) => {
    document.querySelectorAll(`.${cls}`).forEach(el => {
      el.style.display = cols[k] ? '' : 'none';
    });
  });
}

function updateSortHeaders() {
  const fields = ['price','1h','24h','7d','mcap','vol'];
  const ids    = {price:'sort-price','1h':'sort-1h','24h':'sort-24h','7d':'sort-7d',marketCap:'sort-mcap',volume:'sort-vol'};
  Object.entries(ids).forEach(([field,id]) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (state.sortField === field) {
      el.className = 'sort-icon ' + state.sortDir;
    } else {
      el.className = 'sort-icon none';
    }
  });
}

// ═══════════════════════════════════════════════════════════════
//  INTERACTIONS
// ═══════════════════════════════════════════════════════════════
function switchCat(btn, cat) {
  document.querySelectorAll('#categoryTabs .filter-tab').forEach(b => {
    b.classList.remove('active');
    b.setAttribute('aria-selected','false');
  });
  btn.classList.add('active');
  btn.setAttribute('aria-selected','true');
  state.currentCat = cat;
  state.currentPage = 1;
  renderTable();
}

function switchNet(btn, net) {
  document.querySelectorAll('#networkTabs .network-tab').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  state.currentNet = net;
  state.currentPage = 1;
  renderTable();
}

function sortBy(field) {
  if (state.sortField === field) {
    state.sortDir = state.sortDir === 'desc' ? 'asc' : 'desc';
  } else {
    state.sortField = field;
    state.sortDir = 'desc';
  }
  renderTable();
}

function toggleStar(e, rank) {
  e.stopPropagation();
  if (state.starred.has(rank)) state.starred.delete(rank);
  else state.starred.add(rank);
  renderTable();
}

function toggleColumns() {
  const panel = document.getElementById('columnsPanel');
  const btn = document.getElementById('columnsBtn');
  const isOpen = panel.classList.toggle('open');
  btn.classList.toggle('active', isOpen);
  btn.setAttribute('aria-expanded', String(isOpen));
}

function toggleFilters() {
  const panel = document.getElementById('filtersPanel');
  const btn = document.getElementById('filtersBtn');
  const isOpen = panel.classList.toggle('open');
  btn.classList.toggle('active', isOpen);
  btn.setAttribute('aria-expanded', String(isOpen));
}

function toggleCol(key) {
  state.cols[key] = !state.cols[key];
  const sw = document.getElementById('col-' + key);
  if (sw) sw.classList.toggle('on', state.cols[key]);
  updateColVisibility();
}

function applyFilters() {
  toggleFilters();
  renderTable();
}

function resetFilters() {
  document.getElementById('f-price-min').value = '';
  document.getElementById('f-price-max').value = '';
  document.getElementById('f-mcap').value = 'All';
  document.getElementById('f-change').value = 'All';
  document.getElementById('f-category').value = 'All';
  renderTable();
}

function toggleSummary() {
  const extra = document.getElementById('marketSummaryExtra');
  const btn   = document.getElementById('readMoreBtn');
  const isOpen = extra.classList.toggle('open');
  btn.classList.toggle('open', isOpen);
  btn.setAttribute('aria-expanded', String(isOpen));
  btn.innerHTML = isOpen
    ? 'Show Less <span class="arrow-icon" style="display:inline-block;transform:rotate(180deg)">▾</span>'
    : 'Read More <span class="arrow-icon">▾</span>';
}

// ─── Pagination ──────────────────────────────────
let currentPageNum = 1;
const TOTAL_PAGES = 84;

function goToPage(n) {
  currentPageNum = n;
  state.currentPage = n;
  renderTable();
  buildPagination(n);
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

function prevPage() {
  if (currentPageNum > 1) goToPage(currentPageNum - 1);
}

function nextPage() {
  if (currentPageNum < TOTAL_PAGES) goToPage(currentPageNum + 1);
}

function buildPagination(current) {
  const pg = document.getElementById('pagination');
  let pages = [];
  if (TOTAL_PAGES <= 7) {
    pages = Array.from({length:TOTAL_PAGES},(_,i)=>i+1);
  } else {
    pages = [1,2,3,4,'…',TOTAL_PAGES];
    if (current > 4 && current < TOTAL_PAGES - 2) {
      pages = [1,'…',current-1,current,current+1,'…',TOTAL_PAGES];
    } else if (current >= TOTAL_PAGES - 2) {
      pages = [1,'…',TOTAL_PAGES-3,TOTAL_PAGES-2,TOTAL_PAGES-1,TOTAL_PAGES];
    }
  }

  let html = `<button class="page-btn" onclick="prevPage()" aria-label="Previous page">&#8249;</button>`;
  pages.forEach(p => {
    if (p === '…') {
      html += `<button class="page-btn dots" aria-hidden="true">…</button>`;
    } else {
      html += `<button class="page-btn ${p===current?'active':''}" onclick="goToPage(${p})" aria-label="Page ${p}" ${p===current?'aria-current="page"':''}>${p}</button>`;
    }
  });
  html += `<button class="page-btn" onclick="nextPage()" aria-label="Next page">&#8250;</button>`;
  pg.innerHTML = html;
}

// ─── Promo Carousel ──────────────────────────────
let slideIdx = 0;
const slides = document.querySelectorAll('.promo-slide');
const dots   = document.querySelectorAll('.promo-dot');

function goToSlide(i) {
  slides[slideIdx].classList.remove('active');
  dots[slideIdx].classList.remove('active');
  slideIdx = (i + slides.length) % slides.length;
  slides[slideIdx].classList.add('active');
  dots[slideIdx].classList.add('active');
}

function nextSlide() { goToSlide(slideIdx + 1); }
function prevSlide() { goToSlide(slideIdx - 1); }

let autoSlide = setInterval(nextSlide, 5000);
document.querySelector('.promo-banner').addEventListener('mouseenter', () => clearInterval(autoSlide));
document.querySelector('.promo-banner').addEventListener('mouseleave', () => {
  autoSlide = setInterval(nextSlide, 5000);
});

// ─── Close dropdowns on outside click ───────────
document.addEventListener('click', e => {
  if (!e.target.closest('#columnsBtn') && !e.target.closest('#columnsPanel')) {
    const panel = document.getElementById('columnsPanel');
    const btn   = document.getElementById('columnsBtn');
    if (panel.classList.contains('open')) {
      panel.classList.remove('open');
      btn.classList.remove('active');
      btn.setAttribute('aria-expanded','false');
    }
  }
});

// ─── Keyboard navigation for table rows ─────────
document.getElementById('tableBody').addEventListener('keydown', e => {
  if (e.key === 'Enter' || e.key === ' ') {
    const row = e.target.closest('tr');
    if (row) row.click();
  }
});

// ═══════════════════════════════════════════════════════════════
//  INIT
// ═══════════════════════════════════════════════════════════════
renderTable();
buildPagination(1);

// Live price ticker simulation (subtle updates)
setInterval(() => {
  allCoins.forEach(c => {
    c.price *= 1 + (Math.random()-0.5)*0.0001;
    c.h1 += (Math.random()-0.5)*0.01;
  });
  // Only re-render if table is in view to avoid jank
  const table = document.getElementById('cryptoTable');
  const rect = table.getBoundingClientRect();
  if (rect.top < window.innerHeight && rect.bottom > 0) {
    renderTable();
  }
}, 8000);
</script>
